private:
    string name;
    int age, id;
    int s1, s2, s3, s4;
    double avg;
public:
    void input() {
        getline(cin, name, ',');
        char c;
        cin >> age >> c >> id >> c >> s1 >> c >> s2 >> c >> s3 >> c >> s4;
    }
    void calculate() {
        avg = (s1 + s2 + s3 + s4) / 4.0;
    }
    void output() {
        cout << name << ',' << age << ',' << id << ',';
        if (avg == int(avg)) cout << int(avg);
        else cout << avg;
        cout << endl;
    }

